# Projetos práticos: guias em texto, sem código pronto.
# Feitos no próprio computador (VS Code + Python instalado), não executados no site.


def S(titulo, texto, dica=""):
    return {"titulo": titulo, "texto": texto, "dica": dica}


def P(id, titulo, nivel, tempo, resumo, stack, fonte, contexto, objetivo, aprende, etapas, criterios, extras,
      preparo=None, cuidados=None, entrega=None):
    d = dict(id=id, titulo=titulo, nivel=nivel, tempo=tempo, resumo=resumo, stack=stack, fonte=fonte,
             contexto=contexto, objetivo=objetivo, aprende=aprende, etapas=etapas, criterios=criterios, extras=extras)
    if preparo:
        d["preparo"] = preparo
    if cuidados:
        d["cuidados"] = cuidados
    if entrega:
        d["entrega"] = entrega
    return d


